import { beforeEach, describe, expect, it } from "vitest";
import type { SkillState } from "../types";
import { setEngineType, setSkillState } from "./actions";
import { initInspectorStore, inspectorStore } from "./InspectorStore";

const skillState: SkillState = {
  active_skill: {
    skill_id: "card_replace",
    ordered_block_id: "card_replace__main",
    step_id: "start",
  },
  blocks: { card_replace__main: { status: "active" } },
  evaluated_conditions: { "session.card_replace.ready": true },
  tools: {},
  llm_calls: [],
  memory: {
    "card_replace.reason": { value: "lost", source: "llm", scope: "skill", description: null },
  },
};

describe("setSkillState", () => {
  beforeEach(() => {
    initInspectorStore();
  });

  it("keeps the previous skillState when called with undefined", () => {
    // Malformed or absent tracker payloads parse to undefined; they must not
    // blank the pane mid-conversation.
    setSkillState(skillState);
    setSkillState(undefined);
    expect(inspectorStore.state.skillState).toEqual(skillState);
  });

  it("replaces the skillState when called with a value", () => {
    expect(inspectorStore.state.skillState).toBeNull();
    setSkillState(skillState);
    expect(inspectorStore.state.skillState).toEqual(skillState);
  });

  it("clears the skillState when called with null", () => {
    setSkillState(skillState);
    setSkillState(null);
    expect(inspectorStore.state.skillState).toBeNull();
  });

  it("records the active skill as the last-active ref", () => {
    setSkillState(skillState);
    expect(inspectorStore.state.lastActiveSkillRef).toEqual(skillState.active_skill);
  });

  it("keeps the last-active ref while routing between skills", () => {
    // A skillState with a null active_skill is the between-skills gap; the pane
    // keeps showing the previous skill via this ref rather than blanking.
    setSkillState(skillState);
    setSkillState({ ...skillState, active_skill: null });
    expect(inspectorStore.state.lastActiveSkillRef).toEqual(skillState.active_skill);
  });

  it("resets the last-active ref on an explicit clear", () => {
    setSkillState(skillState);
    setSkillState(null);
    expect(inspectorStore.state.lastActiveSkillRef).toBeNull();
  });
});

describe("setEngineType", () => {
  beforeEach(() => {
    initInspectorStore();
  });

  it("defaults to calm and flips to the declared engine", () => {
    expect(inspectorStore.state.engineType).toBe("calm");
    setEngineType("mantle");
    expect(inspectorStore.state.engineType).toBe("mantle");
    setEngineType("calm");
    expect(inspectorStore.state.engineType).toBe("calm");
  });
});
